package ru.neverland.runtime;
import java.nio.file.*;
import java.util.*;
import java.util.function.Consumer;
import org.bukkit.*;
import org.bukkit.block.BlockFace;
import com.palmergames.bukkit.towny.*;
import com.palmergames.bukkit.towny.object.*;
import ru.neverland.townydistricts.*;
import ru.neverland.townydistricts.model.*;
import ru.neverland.townydistricts.model.District;
import ru.neverland.townydistricts.service.*;
import ru.neverland.townybuilds.data.DataStore;
import ru.neverland.townybuilds.construction.*;
import ru.neverland.core.*;

/** Genuine Towny claims and Builds footprint API; completed construction sites are an explicit persisted fixture. */
public final class DistrictAssessmentProbe extends AdmissionsProbe {
    NeverLandTownyDistricts districtsPlugin;DistrictService districts;AssessmentService assessment;DataStore buildings;byte[] districtFile;
    @SuppressWarnings("unchecked")Map<String,Map<String,Object>> rows(Map<String,Object> report){return(Map<String,Map<String,Object>>)report.get("rows");}
    void ready(int remaining,Consumer<Map<String,Object>> next)throws Exception{var report=districts.assessment(T);if(Boolean.TRUE.equals(report.get("available"))){next.accept(report);return;}if(!Boolean.TRUE.equals(report.get("pending"))||remaining<=0)throw new AssertionError("assessment did not become ready: "+report);later(1,()->ready(remaining-1,next));}
    void in(Work work){try{work.run();}catch(Throwable error){fail(error);}}
    @Override void setup()throws Exception{
        districtsPlugin=(NeverLandTownyDistricts)Bukkit.getPluginManager().getPlugin("NeverLandTownyDistricts");districts=(DistrictService)field(districtsPlugin,"service");assessment=(AssessmentService)field(districtsPlugin,"assessments");buildings=(DataStore)field(Bukkit.getPluginManager().getPlugin("NeverLandTownyBuilds"),"dataStore");mayor=actor(M,"DistrictPlannerMayor");check(districtsPlugin.isEnabled()&&districtsPlugin.getDescription().getVersion().equals("0.2.1"),"actual Districts 0.2.1 and Builds footprint bridge enabled on Folia");
        if(restart){town=TownyAPI.getInstance().getTown(T);ready(80,r->in(()->resumeAssessment(r)));return;}
        var u=TownyUniverse.getInstance();u.newTownInternal("PlannerCity",T);town=TownyAPI.getInstance().getTown(T);var resident=u.getDataSource().newResident("DistrictPlannerMayor",M);resident.setTown(town);town.setMayor(resident);resident.save();
        for(int x=-1;x<=12;x++)for(int z=-2;z<=2;z++){var claim=new TownBlock(x,z,u.getWorld(world.getName()));u.addTownBlock(claim);claim.setTown(town);if(x==0&&z==0)town.setHomeBlock(claim);claim.save();}var island=new TownBlock(20,0,u.getWorld(world.getName()));u.addTownBlock(island);island.setTown(town);island.save();town.setSpawn(origin);town.save();
        for(var e:Map.of("town_hall",0,"forge",4,"foundry",7,"warehouse",10,"workshop",6).entrySet()){int level=e.getKey().equals("workshop")?1:5;var site=new ConstructionSite(e.getKey(),world.getUID(),e.getValue()*16+8,160,8,BlockFace.NORTH,level,level,1,false);site.blueprintSet(BlueprintCatalog.currentPin(e.getKey(),BuildingStyle.MEDIEVAL));buildings.town(T).setConstructionSite(site);buildings.town(T).setLevel(e.getKey(),level);}buildings.markDirty();buildings.saveOrThrow();
        var cells=new HashSet<Cell>();for(int x=2;x<=12;x++)for(int z=-2;z<=2;z++)cells.add(new Cell(world.getUID(),x,z));districts.put(new District(T,"industrial","Мастерские",DistrictType.INDUSTRIAL,cells),true);districts.put(new District(T,"outpost","Дальний порт",DistrictType.PORT,Set.of(new Cell(world.getUID(),20,0))),true);
        check(districts.view(T).buildings().size()==5&&districts.view(T).buildings().stream().allMatch(b->b.level()>0&&b.requiredLevel()==5),"real Builds API supplies five completed registered-site footprints including current level I without world scanning");check(Math.abs(districts.multiplier(T,"forge")-1.35)<1e-8,"existing industrial matching and three-building bonus retained before assessment");
        districtFile=Files.readAllBytes(districtsPlugin.getDataFolder().toPath().resolve("districts-data.yml"));check(Boolean.TRUE.equals(districts.assessment(T).get("pending")),"first API request returns pending without blocking region for graph work");ready(80,r->in(()->baseline(r)));
    }
    @SuppressWarnings("unchecked")void baseline(Map<String,Object> report)throws Exception{
        check(report.get("format").equals(2)&&((Map<?,?>)report.get("assignments")).get("workshop").equals("industrial"),"coherent format-2 snapshot exposes real physical assignment of completed level-I workshop");
        var rows=rows(report);var industry=rows.get("industrial");var port=rows.get("outpost");check(Boolean.TRUE.equals(report.get("homeKnown"))&&industry.get("connected").equals(industry.get("total"))&&port.get("connected").equals(0),"real adjacent Towny claims connect industrial district while remote outpost stays disconnected");check(industry.get("matching").equals(4)&&industry.get("other").equals(0),"assessment recognizes actual forge, foundry, warehouse and level-I workshop profile without counting outside town hall");var services=(Map<String,Map<String,Object>>)industry.get("services");check(Boolean.TRUE.equals(services.get("storage").get("known"))&&((Number)services.get("storage").get("served")).intValue()>0&&((List<?>)services.get("storage").get("sources")).contains("warehouse"),"actual warehouse footprint supplies nearby district cells along owned land");check(Boolean.TRUE.equals(services.get("power").get("known"))&&services.get("power").get("served").equals(0),"known absent energy facility remains distinct from missing provider data");
        districtsPlugin.getCommand("townydistricts").execute(mayor,"districts",new String[]{"assess","industrial"});check(windows.get(M).getSize()==54&&windows.get(M).getItem(10).getType()==Material.COMPARATOR&&lore(mayor,10).contains("Ближайшие")&&lore(mayor,4).contains("МСК"),"actual command opens native profile, coverage and Moscow-dated explanation cards");
        check(Arrays.equals(districtFile,Files.readAllBytes(districtsPlugin.getDataFolder().toPath().resolve("districts-data.yml")))&&Math.abs(districts.multiplier(T,"forge")-1.35)<1e-8,"assessment API and menu do not rewrite district data or alter old production multiplier");
        town.setHomeBlock(TownyUniverse.getInstance().getTownBlock(new WorldCoord(world.getName(),20,0)));check(Boolean.TRUE.equals(districts.assessment(T).get("pending")),"changed central claim invalidates old report instead of presenting stale connection as current");ready(80,r->in(()->movedHome(r)));
    }
    void movedHome(Map<String,Object> report)throws Exception{check(rows(report).get("industrial").get("connected").equals(0)&&rows(report).get("outpost").get("connected").equals(1),"new genuine Towny home changes graph component without loading remote chunks");town.setHomeBlock(TownyUniverse.getInstance().getTownBlock(new WorldCoord(world.getName(),0,0)));town.save();ready(80,r->in(()->toggleAndFinish(r)));}
    void toggleAndFinish(Map<String,Object> report)throws Exception{check(rows(report).get("industrial").get("connected").equals(rows(report).get("industrial").get("total")),"restored town centre recalculates exact prior connectivity");districtsPlugin.getConfig().set("assessment.enabled",false);check(Boolean.FALSE.equals(districts.assessment(T).get("available"))&&Math.abs(districts.multiplier(T,"forge")-1.35)<1e-8&&Arrays.equals(districtFile,Files.readAllBytes(districtsPlugin.getDataFolder().toPath().resolve("districts-data.yml"))),"neutral feature disable preserves old district data and all industrial bonuses");districtsPlugin.getConfig().set("assessment.enabled",true);districtsPlugin.getConfig().set("assessment.service-range-cells","broken");assessment.reload();check(Boolean.FALSE.equals(districts.assessment(T).get("available"))&&Math.abs(districts.multiplier(T,"forge")-1.35)<1e-8,"bad optional assessment settings pause only assessment, not districts or existing effects");districtsPlugin.getConfig().set("assessment.service-range-cells",8);assessment.reload();ready(80,r->in(this::finishAssessment));}
    void resumeAssessment(Map<String,Object> report)throws Exception{check(town!=null&&districts.list(T).size()==2&&districts.view(T).buildings().size()==5,"actual persisted districts and completed building sites survive native restart");check(rows(report).get("industrial").get("matching").equals(4)&&rows(report).get("industrial").get("connected").equals(rows(report).get("industrial").get("total"))&&rows(report).get("outpost").get("connected").equals(0),"derived report reconstructs identical profile and connectivity after restart");check(Math.abs(districts.multiplier(T,"forge")-1.35)<1e-8,"original industrial multiplier remains unchanged after restart");districtsPlugin.getCommand("townydistricts").execute(mayor,"districts",new String[]{"assess"});check(windows.get(M).getItem(10)!=null&&windows.get(M).getItem(11)!=null&&windows.get(M).getItem(49).getType()==Material.SUNFLOWER,"restored native assessment board contains both districts and usable refresh action");finishAssessment();}
    void finishAssessment()throws Exception{TownyUniverse.getInstance().getDataSource().saveAll();Files.writeString(proof.resolve((restart?"restart":"first")+"-passed.txt"),"PASS "+checks+" assertions; genuine Folia/Towny/Builds/Districts metadata, real immutable footprint API, native command/menu, detached graph, exact source invalidation, read-only file checks, neutral feature failure and full restart; explicit offline Player/InventoryView/EntityScheduler and completed-site fixtures; no graphical client, purchased construction, block scanning or bank operation claimed\n");Bukkit.getGlobalRegionScheduler().run(this,t->Bukkit.shutdown());}
}
